	'lang_label' => 'Langue',
	'led1_p' => 'Fissures, linteaux, planchers et cheminée, avec la largeur et la direction de tout mouvement visible.',
	'led1_t' => 'Structure et mouvements',
	'led2_p' => 'Couvertures, solins, gouttières et descentes d\'eau pluviale, observés depuis le sol, une échelle courte ou une caméra sur perche.',
	'led2_t' => 'Toiture et eaux pluviales',
	'led3_p' => 'Relevés d\'humidité, grilles d\'aération et condensation, rédigés pour qu\'une auréole ne soit pas assimilée à des remontées capillaires.',
	'led3_t' => 'Humidité et ventilation',
	'led4_p' => 'Murs extérieurs, menuiseries et ouvertures, y compris appuis et linteaux au-dessus des baies.',
	'led4_t' => 'Murs, fenêtres et portes',
	'led5_p' => 'Installations électriques visibles, chauffage et regards d\'évacuation. Il s\'agit d\'un examen visuel uniquement, sans test des réseaux.',
	'led5_t' => 'Réseaux visibles',
	'led6_p' => 'Plafonds, escaliers et issues de secours, y compris l\'itinéraire d\'évacuation d\'un appartement situé en étage.',
	'led6_t' => 'Intérieur',
	'led7_p' => 'Clôtures, allées, dépendances et arbres à proximité des murs.',
	'led7_t' => 'Extérieur',
	'led8_p' => 'Trois colonnes : interventions immédiates, d\'ici deux ans, et éléments à surveiller, chacune avec une fourchette indicative de coût.',
